------------------------------------------------------
# pytorch/hyperbolic_models.py
import torch
from torch import nn
from hyperbolic_parameter import PoincareParameter, EuclideanParameter, SphericalParameter, HyperboloidParameter

class ProductEmbedding(nn.Module):
    def __init__(self, n, hyp_d, hyp_copies=1, euc_d=1, euc_copies=0, sph_d=1, sph_copies=0, project=True, initialize=None, learn_scale=False, initial_scale=0.0, absolute_loss=False, logrel_loss=False, dist_loss=False, square_loss=False, sym_loss=False, exponential_rescale=None, riemann=False):
        super(ProductEmbedding, self).__init__()
        self.n = n
        self.riemann = riemann
        # Create hyperbolic embeddings using the appropriate parameter class
        self.H = nn.ModuleList([
            Embedding(HyperboloidParameter.dist_h, HyperboloidParameter, n, hyp_d, project, initialize, learn_scale, initial_scale)
            for _ in range(hyp_copies)])
        # Similarly, Euclidean and Spherical embeddings can be added
        self.E = nn.ModuleList([
            Embedding(lambda u,v: torch.norm(u-v, 2, dim=1), EuclideanParameter, n, euc_d, False, initialize, False, initial_scale)
            for _ in range(euc_copies)])
        self.S = nn.ModuleList([
            Embedding(lambda u,v: torch.acos(torch.clamp(torch.sum(u*v, dim=-1), -1+1e-9, 1-1e-9)), SphericalParameter, n, sph_d, project, initialize, learn_scale, initial_scale)
            for _ in range(sph_copies)])

        # Collect scale parameters and embeddings for optimization
        self.scale_params = [H.scale_log for H in self.H] + [E.scale_log for E in self.E] + [S.scale_log for S in self.S] if learn_scale else []
        self.hyp_params = [H.w for H in self.H]
        self.euc_params = [E.w for E in self.E]
        self.sph_params = [S.w for S in self.S]
        self.embed_params = self.hyp_params + self.euc_params + self.sph_params

        # Loss configuration
        self.absolute_loss = absolute_loss
        self.logrel_loss = logrel_loss
        self.dist_loss = dist_loss
        self.square_loss = square_loss
        self.sym_loss = sym_loss
        self.exponential_rescale = exponential_rescale

    def dist_idx(self, idx):
        # Compute distances for a batch of index pairs
        d_list = [emb.dist_idx(idx) for emb in self.H]
        if self.riemann:
            return torch.norm(torch.stack(d_list), 2, dim=0)
        else:
            return sum(d_list)

    def loss(self, _x):
        # _x contains a tuple of (index pairs, true distances, weights)
        idx, values, w = _x
        d = self.dist_idx(idx)
        term_rescale = w
        if self.absolute_loss:
            loss = torch.sum(term_rescale * (d - values)**2)
        elif self.logrel_loss:
            loss = torch.sum(torch.log((d/values)**2)**2)
        elif self.dist_loss:
            loss = torch.sum(torch.abs(term_rescale * ((d/values) - 1)))
        elif self.square_loss:
            loss = torch.sum(term_rescale * torch.abs((d/values)**2 - 1))
        else:
            l1 = torch.sum(term_rescale * ((d/values) - 1)**2)
            l2 = torch.sum(term_rescale * ((values/d) - 1)**2) if self.sym_loss else 0
            loss = l1 + l2
        return loss / values.size(0)

    def normalize(self):
        for H in self.H:
            H.normalize()
        for S in self.S:
            S.normalize()

class Embedding(nn.Module):
    def __init__(self, dist_fn, param_cls, n, d, project=True, initialize=None, learn_scale=False, initial_scale=0.0):
        super(Embedding, self).__init__()
        self.dist_fn = dist_fn
        self.n, self.d = n, d
        self.project = project
        # Initialize the embedding parameter for n points in d dimensions
        self.w = param_cls(data=initialize, sizes=(n, d))
        if learn_scale:
            self.scale_log = nn.Parameter(torch.tensor([initial_scale], dtype=torch.double))
        else:
            self.scale_log = torch.tensor([initial_scale], dtype=torch.double, device=self.w.device)

    def scale(self):
        return torch.exp(self.scale_log)

    def dist_idx(self, idx):
        wi = torch.index_select(self.w, 0, idx[:, 0])
        wj = torch.index_select(self.w, 0, idx[:, 1])
        d = self.dist_fn(wi, wj)
        return d * self.scale()

    def normalize(self):
        # Project the parameters to satisfy manifold constraints
        self.w.proj()
